contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool asDeployer) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint256 beforeC = address(c).balance;
        uint256 beforeSelf = address(this).balance;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterC = address(c).balance;
        uint256 afterSelf = address(this).balance;
        assert(
            (reverted && afterC == beforeC && afterSelf == beforeSelf) ||
            (!reverted && afterC == 0 && afterSelf >= beforeSelf)
        );
    }

    receive() external payable {}
}

