// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool asDeployer) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeC = address(c).balance;
        uint256 beforeSelf = address(this).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterC = address(c).balance;
        uint256 afterSelf = address(this).balance;
        assertTrue((reverted && afterC == beforeC && afterSelf == beforeSelf) ||
            (!reverted && afterC == 0 && afterSelf >= beforeSelf));
    }

    function testFuzz_run(bool asDeployer) public {
        _run(asDeployer);
    }

    receive() external payable {}
}
